withLabelsCode.web:
// A palavra de cada um dos cinco estados e o molde do código de saída.
//
// Os cinco existem porque um comando passa por todos: fica na fila, corre, é
// interrompido por quem lê, termina ou quebra. Interrompido não é falha — é o
// Ctrl-C —, e por isso as duas palavras são diferentes.
//
// O molde é molde porque a palavra que apresenta o número é do idioma, e o
// número é dado. Ele não julga o número: há comando que devolve um sem ter
// falhado.
const rotulos = {
  status: {
    idle: 'Em espera',
    running: 'Em andamento',
    stopped: 'Interrompido',
    complete: 'Concluído',
    failed: 'Falhou',
  },
  exitCode: 'código de saída {code}',
};

extensibilityCode.web:
// O CÓDIGO DE SAÍDA SÓ EXISTE DEPOIS DO FIM, e quem responde é o vocabulário
// compartilhado — não um teste escrito na tela.
isRunFinished('running');   // false → nada de código de saída ainda
isRunFinished('stopped');   // true  → parado por gente também é fim
isRunFinished('complete');  // true
isRunFinished('failed');    // true

// E O NÚMERO NÃO DECIDE NADA. Zero é sucesso por convenção, mas há comando que
// devolve 1 sem ter falhado: um busca e não acha, outro compara e encontra
// diferença. Quem diz o que aconteceu é o estado, que vem de quem executou.
//
// Derivar um do outro daria duas fontes de verdade que podem discordar — o
// mesmo defeito que o vocabulário evita ao deixar o total de tokens ser função
// em vez de campo.

customizationCode.web:
.nds-terminal-block {
  /* O teto da saída é uma custom property, e ele é em `rem` de propósito:
     assim ele cresce com a fonte do navegador em vez de espremer mais linhas
     no mesmo espaço quando alguém aumenta o texto. */
  --terminal-block-max-block-size: 32rem;
}

/* A cor do ponto é REFORÇO, e não a pista: a palavra ao lado é o que descreve
   o estado. Mexer no ponto não muda o que chega a quem ouve. */
.nds-terminal-block-dot {
  inline-size: var(--spacing-3);
  block-size: var(--spacing-3);
}

