withLabelsCode.web:
// La palabra de cada uno de los cinco estados y la plantilla del código de
// salida.
//
// Los cinco existen porque un comando pasa por todos: espera en la cola, corre,
// es interrumpido por quien lee, termina o se rompe. Interrumpido no es fallo —
// es el Ctrl-C —, y por eso las dos palabras son distintas.
//
// La plantilla es plantilla porque la palabra que presenta el número es del
// idioma, y el número es dato. No juzga el número: hay comandos que devuelven
// uno sin haber fallado.
const rotulos = {
  status: {
    idle: 'En espera',
    running: 'En curso',
    stopped: 'Interrumpido',
    complete: 'Terminado',
    failed: 'Falló',
  },
  exitCode: 'código de salida {code}',
};

extensibilityCode.web:
// EL CÓDIGO DE SALIDA SOLO EXISTE DESPUÉS DEL FINAL, y quien responde es el
// vocabulario compartido — no una prueba escrita en la pantalla.
isRunFinished('running');   // false → todavía no hay código de salida
isRunFinished('stopped');   // true  → detenido por gente también es final
isRunFinished('complete');  // true
isRunFinished('failed');    // true

// Y EL NÚMERO NO DECIDE NADA. Cero es éxito por convención, pero hay comandos
// que devuelven 1 sin haber fallado: uno busca y no encuentra, otro compara y
// encuentra una diferencia. Quien dice lo que pasó es el estado, que viene de
// quien lo ejecutó.
//
// Derivar uno del otro daría dos fuentes de verdad que pueden discrepar — el
// mismo defecto que el vocabulario evita al dejar que el total de tokens sea
// una función en vez de un campo.

customizationCode.web:
.nds-terminal-block {
  /* El techo de la salida es una custom property, y está en `rem` a propósito:
     así crece con la fuente del navegador en vez de apretar más líneas en el
     mismo espacio cuando alguien agranda el texto. */
  --terminal-block-max-block-size: 32rem;
}

/* El color del punto es REFUERZO, y no la pista: la palabra de al lado es lo
   que describe el estado. Tocar el punto no cambia lo que llega a quien
   escucha. */
.nds-terminal-block-dot {
  inline-size: var(--spacing-3);
  block-size: var(--spacing-3);
}
